key.query:
query GetSiteSettingsBanner {
  page(id: "site-settings", idType: URI) {
    affiliatedBanner {
      bannerType
      bannerHeadline
      bannerSubtext
      bannerCtaLabel
      bannerCtaUrl
      openInNewTab
      bannerEnabled
      bannerImage {
        node {
          sourceUrl
          altText
          mediaDetails {
            sizes {
              name
              sourceUrl
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
